import React from 'react';
import { Alert, Button, Stack, Typography } from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import {
  myCompanyPageChecks,
  type MyCompanyPageId,
} from '../utils/myCompanyRequired';

type MyCompanyRequiredNoticeProps = {
  profile: unknown;
  pageId?: MyCompanyPageId;
};

const MyCompanyRequiredNotice: React.FC<MyCompanyRequiredNoticeProps> = ({ profile, pageId }) => {
  const checks = myCompanyPageChecks(profile as Parameters<typeof myCompanyPageChecks>[0]);
  const current = pageId ? checks.find((page) => page.id === pageId) : null;
  if (current?.complete) return null;
  const open = current ? [current] : checks.filter((page) => !page.complete);
  if (open.length === 0) return null;

  return (
    <Alert severity="warning" sx={{ mb: 2 }}>
      <Typography variant="body2" sx={{ mb: 1 }}>
        {pageId
          ? 'Save this page before the rest of the workspace opens.'
          : 'Fill every My company page before the rest of the workspace opens. The report base year is the earliest year on the transactions you add.'}
      </Typography>
      <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
        {open.map((page) => (
          <Button
            key={page.id}
            component={RouterLink}
            to={page.path}
            size="small"
            variant="outlined"
            color="inherit"
          >
            {page.label}: {page.missing[0]}
          </Button>
        ))}
      </Stack>
    </Alert>
  );
};

export default MyCompanyRequiredNotice;
