/**
 * Normalize phone display/save values (DEEP-BUG-038).
 * Strips non-digits except a leading +, and collapses accidental concatenations
 * (e.g. repeated numbers glued together) to a single Indian mobile when possible.
 */
export function normalizePhoneInput(raw: unknown): string {
  const text = String(raw ?? '').trim();
  if (!text) return '';

  const hasPlus = text.startsWith('+');
  const digits = text.replace(/\D/g, '');
  if (!digits) return '';

  // Prefer last 10 digits when value looks like concatenated Indian mobiles.
  if (digits.length > 12 && digits.length % 10 === 0) {
    return `${hasPlus ? '+' : ''}${digits.slice(-10)}`;
  }
  if (digits.length > 12 && digits.endsWith(digits.slice(0, digits.length - 10))) {
    return `${hasPlus ? '+' : ''}${digits.slice(-10)}`;
  }
  // Common: 91XXXXXXXXXX or 0XXXXXXXXXX
  if (digits.length === 12 && digits.startsWith('91')) {
    return `${hasPlus ? '+' : ''}${digits}`;
  }
  if (digits.length > 15) {
    return `${hasPlus ? '+' : ''}${digits.slice(-12)}`;
  }
  return `${hasPlus ? '+' : ''}${digits}`;
}
